pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base penalty: logarithmic of the residual after placement.
    let base = (post_residual as f64 + 1.0).ln();

    // How tightly the item fills the bin before placement.
    let ratio = item_size as f64 / (bin_residual as f64 + 1.0);
    let ratio_penalty = (1.0 - ratio).powi(2) * 12.0;

    // Deviation from average residual across all bins.
    let residual_dev = (post_residual as f64 - mean_residual).abs() * 0.5;

    // Penalty if the next item will not fit.
    let next_fit_penalty = if next_item_size > post_residual { 20.0 } else { 0.0 };

    // New‑bin bias: discourage opening a new bin when many are already open.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if open_bins_count > 5 { 6.0 } else { 0.0 }
    } else { 0.0 };

    // Incentive to open a new bin when only one fitting bin exists.
    let fitting_bias = if fitting_bins_count == 1 { 3.0 } else { 0.0 };

    // Reward for a perfect fit.
    let perfect_fit_bonus = if post_residual == 0 { -1.0 } else { 0.0 };

    // Penalize high residual after placement (dead space).
    let dead_space_penalty = (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Bonus for placing items that almost fill the bin.
    let fit_density_bonus = if ratio > 0.95 {
        -2.5
    } else if ratio > 0.9 {
        -1.5
    } else {
        0.0
    };

    // Bonus if the next item fits in the same bin.
    let lookahead_bonus = if next_item_size <= post_residual { -3.0 } else { 0.0 };

    // Extra penalty for using many open bins.
    let open_bins_penalty = if open_bins_count > 8 { 4.0 } else { 0.0 };

    let mut score = base
        + ratio_penalty
        + residual_dev
        + next_fit_penalty
        + new_bin_penalty
        + fitting_bias
        + perfect_fit_bonus
        + dead_space_penalty
        + fit_density_bonus
        + lookahead_bonus
        + open_bins_penalty;

    // Slightly amplify penalties for later steps to encourage earlier packing.
    if step_index > total_items / 2 {
        score *= 1.05;
    }

    score
}

