pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base cost grows logarithmically with the residual after placement.
    let base = (post_residual as f64 + 1.0).ln() * 1.0;

    // Fullness penalty: we prefer bins that are as full as possible.
    let fullness_penalty = (post_residual as f64 / bin_capacity as f64).powi(3) * 8.0;

    // Deviation from the mean residual to keep the distribution tight.
    let dev = ((post_residual as f64) - mean_residual).powi(2) * 0.2;

    // Lookahead penalty: if the next item does not fit, we prefer a bin
    // that leaves enough space for it.
    let next_gap = if next_item_size > post_residual {
        ((next_item_size as f64 - post_residual as f64).powi(2)) * 0.6
    } else {
        0.0
    };

    // New‑bin bias: discourage opening a new bin when many are already open
    // or when the average residual is already low.
    let mut new_bin_penalty = 0.0;
    if bin_residual == bin_capacity {
        // More open bins increase the penalty, but we temper it with a square‑root.
        let open_factor = (open_bins_count as f64).sqrt() * 0.5;
        let mean_factor = if mean_residual < (bin_capacity as f64 * 0.2) {
            2.0
        } else {
            1.0
        };
        new_bin_penalty = 5.0 + open_factor - mean_factor;

        // Favor new bins earlier in the stream.
        if step_index < total_items / 4 {
            new_bin_penalty *= 0.8;
        }
        // Reduce the penalty slightly in the second half of the stream.
        if step_index > total_items / 3 {
            new_bin_penalty *= 0.7;
        }
    }

    // Fitting bias: if many bins can fit the item, prefer the one that
    // leaves the least residual after placement.
    let fitting_bias = if fitting_bins_count > 1 { -0.3 } else { 0.2 };

    // Perfect‑fit bonus: zero residual after placement.
    let perfect_fit_bonus = if post_residual == 0 { -2.0 } else { 0.0 };

    // Dead‑space penalty: discourage leaving a large fraction of the bin unused.
    let dead_space_penalty = (post_residual as f64 / bin_capacity as f64).powi(2) * 4.0;

    // Size‑ratio penalty: heavily penalise leaving too much space relative
    // to the item size itself.
    let size_ratio_penalty =
        ((post_residual as f64) / (item_size as f64 + 1.0)).powi(2) * 0.4;

    base
        + fullness_penalty
        + dev
        + next_gap
        + new_bin_penalty
        + fitting_bias
        + perfect_fit_bonus
        + dead_space_penalty
        + size_ratio_penalty
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Residual after placement
    let residual = post_residual as f64;
    let capacity = bin_capacity as f64;
    let residual_frac = residual / capacity;

    // 1️⃣ Base cost: log‑scaled residual, slightly reduced weight
    let base = (residual + 1.0).ln() * 1.05;

    // 2️⃣ Fullness penalty: stronger emphasis on bins near full
    let fullness = (1.0 - residual_frac).powi(2) * 7.0;

    // 3️⃣ Deviation penalty: keep residuals balanced, lighter weight
    let deviation = ((residual - mean_residual).powi(2)) * 0.2;

    // 4️⃣ Next‑item gap penalty: quadratic penalty with lower weight
    let next_gap = if next_item_size > post_residual {
        let diff = (next_item_size - post_residual) as f64;
        diff.powi(2) * 0.5
    } else {
        0.0
    };

    // 5️⃣ New‑bin opening penalty: dynamic thresholds and time weighting
    let new_bin_penalty = if bin_residual == bin_capacity {
        let base_pen = if open_bins_count > 25 {
            14.0
        } else if open_bins_count > 15 {
            9.0
        } else {
            5.0
        };
        let time_factor = if step_index > total_items * 2 / 3 {
            0.6
        } else if step_index > total_items / 3 {
            0.8
        } else {
            1.0
        };
        let mean_factor = if mean_residual < capacity * 0.08 {
            1.4
        } else {
            1.0
        };
        base_pen * time_factor * mean_factor
    } else {
        0.0
    };

    // 6️⃣ Fit‑bias: heavy preference for reuse when many bins fit
    let fitting_bias = if fitting_bins_count > 5 {
        -2.0
    } else if fitting_bins_count > 2 {
        -1.0
    } else {
        1.5
    };

    // 7️⃣ Perfect‑fit bonus
    let perfect_bonus = if residual == 0.0 { -3.0 } else { 0.0 };

    // 8️⃣ Residual‑size coupling penalty/bonus
    let residual_size_penalty = if residual > next_item_size as f64 {
        let diff = residual - next_item_size as f64;
        diff.powi(2) * 0.25
    } else if residual < next_item_size as f64 {
        let diff = next_item_size as f64 - residual;
        diff.powi(2) * 0.15
    } else {
        0.0
    };

    // 9️⃣ Look‑ahead bonus: reward if next item will fit nicely
    let hypot_res = if residual >= next_item_size as f64 {
        residual - next_item_size as f64
    } else {
        residual
    };
    let hypot_frac = hypot_res / capacity;
    let lookahead_bonus = if hypot_frac < 0.15 { -0.7 } else { 0.0 };

    // 🔟 Open bins log penalty
    let open_bins_log = (open_bins_count as f64 + 1.0).ln();
    let open_bins_penalty = open_bins_log * 0.3;

    // 𝟏𝟏 Mean residual influence
    let mean_residual_bonus = if mean_residual > capacity * 0.35 { -0.4 } else { 0.0 };

    // 𝟏𝟎 Dead space ratio penalty (captures dead‑space inefficiency)
    let dead_space_penalty = residual_frac.powi(2) * 2.0;

    base
        + fullness
        + deviation
        + next_gap
        + new_bin_penalty
        + fitting_bias
        + perfect_bonus
        + residual_size_penalty
        + lookahead_bonus
        + open_bins_penalty
        + mean_residual_bonus
        + dead_space_penalty
}

