            1.2
        } else if step_index < total_items / 2 {
            1.0
        } else {
            0.8
        };
        // Mean residual factor – lower mean → lower penalty
        let mean_factor = if mean_residual < capacity * 0.1 {
            0.8
        } else {
            1.0
        };
        base_pen * time_factor * mean_factor
    } else {
        0.0
    };

    // 6️⃣ Fitting bias – stronger when many bins fit
    let fitting_bias = if fitting_bins_count > 0 {
        let ratio =
            fitting_bins_count as f64 / open_bins_count.max(1) as f64;
        if ratio > 0.8 {
            -3.0
        } else if ratio > 0.5 {
            -1.5
        } else {
            1.0
        }
    } else {
        1.0
    };

    // 7️⃣ Perfect‑fit bonus
    let perfect_bonus = if residual == 0.0 { -5.0 } else { 0.0 };

    // 8️⃣ Residual‑size coupling penalty/bonus
    let residual_size_penalty = if residual > next_item_size as f64 {
        let diff = residual - next_item_size as f64;
        diff.powi(2) * 0.25
    } else {
        0.0
    };

    // 9️⃣ Look‑ahead bonus – reward when next item fits nicely
    let lookahead_bonus = if next_item_size <= residual { -0.7 } else { 0.0 };

    // 🔟 Open bins log penalty
    let open_bins_log = (open_bins_count as f64 + 1.0).ln();
    let open_bins_penalty = open_bins_log * 0.3;

    // 𝟏𝟏 Mean residual influence
    let mean_residual_bonus = if mean_residual > capacity * 0.35 { -0.4 } else { 0.0 };

    // 𝟏𝟐 Dead space penalty – captures dead‑space inefficiency
    let dead_space_penalty = residual_frac.powi(2) * 2.0;

    // 𝟏𝟑 Residual vs next item ratio penalty
    let ratio_penalty = if next_item_size > 0 {
        let residual_next_ratio = residual / (next_item_size as f64);
        if residual_next_ratio > 2.0 { 1.0 } else { 0.0 }
    } else {
        0.0
    };

    base
        + fullness
        + deviation
        + next_gap
        + new_bin_penalty
        + fitting_bias
        + perfect_bonus
        + residual_size_penalty
        + lookahead_bonus
        + open_bins_penalty
        + mean_residual_bonus
        + dead_space_penalty
        + ratio_penalty
}

