pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // ------------------------------------------------------------------
    // 1. Base residual score – tighter fits get a lower weight.
    // ------------------------------------------------------------------
    let fit_ratio = bin_residual as f64 / bin_capacity as f64;          // 0.0 .. 1.0
    let residual_weight = 0.85 + 0.15 * (1.0 - fit_ratio);            // tighter → smaller weight
    let bin_factor = 1.0 / ((fitting_bins_count as f64) + 1.0);        // many fitting bins → lower score
    let residual_score = (post_residual as f64) * residual_weight * bin_factor;

    // ------------------------------------------------------------------
    // 2. Anticipate next item – penalise bins that will be too tight.
    // ------------------------------------------------------------------
    let future_gap = if next_item_size > bin_residual {
        (next_item_size - bin_residual) as f64
    } else {
        0.0
    };
    let future_penalty = future_gap * 0.025; // small penalty per unit gap

    // ------------------------------------------------------------------
    // 3. Mean residual deviation penalty – avoid bins that are too far
    //    from the average usage.
    // ------------------------------------------------------------------
    let mean_dev = (bin_residual as f64 - mean_residual).abs();
    let mean_penalty = if mean_dev > 15.0 { 0.005 * mean_dev } else { 0.0 };

    // ------------------------------------------------------------------
    // 4. Open‑bins influence – if many bins are already open, favour
    //    opening a new one unless a tight fit exists.
    // ------------------------------------------------------------------
    let open_factor = if open_bins_count > 15 { 0.5 } else { 1.0 };
    let open_score = residual_score * open_factor;

    // ------------------------------------------------------------------
    // 5. New‑bin candidate bonus – give a negative offset to encourage
    //    opening a new bin only when it is strictly better than the best
    //    existing fit.  The bonus grows with the number of fitting bins.
    // ------------------------------------------------------------------
    let new_bin_bonus = if bin_residual == bin_capacity {
        // More fitting bins → larger negative bonus
        -((fitting_bins_count as f64).ln() + 1.0) * 2.0
    } else {
        0.0
    };

    // ------------------------------------------------------------------
    // 6. Combine everything.
    // ------------------------------------------------------------------
    let mut score = open_score + future_penalty + mean_penalty + new_bin_bonus;

    // ------------------------------------------------------------------
    // 7. Small step‑based tweak – slightly lower score every 30th item
    //    to smooth early decisions.
    // ------------------------------------------------------------------
    if step_index % 30 == 0 {
        score -= 1.0;
    }

    score
}

