        let remaining = (total_items - step_index) as f64 / total_items as f64;
        let mean_factor = 1.0 - (mean_residual / cap_f).min(1.0);
        4.5 * open_factor * remaining * mean_factor
    } else {
        0.0
    };

    // 7️⃣ Fitting bias – encourage using a bin when many options exist
    let fitting_bias = if fitting_bins_count > 5 { -0.8 } else { 1.0 };

    // 8️⃣ Perfect‑fit bonus
    let perfect = if res_f == 0.0 { -5.0 } else { 0.0 };

    // 9️⃣ Dead‑space penalty
    let dead = if res_f > next_item_size as f64 * 2.0 {
        ((res_f - next_item_size as f64 * 2.0).powi(2)) * 0.5
    } else {
        0.0
    };

    // 🔟 Small residual bonus – reuse almost‑full bins
    let small = if res_f > 0.0 && res_f < cap_f * 0.03 { -1.0 } else { 0.0 };

    // 1️⃣1️⃣ Residual vs next‑item ratio penalty
    let ratio_penalty = if next_item_size > 0 {
        let r = res_f / next_item_size as f64;
        if r > 1.5 {
            (r - 1.5).powi(2) * 0.3
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 1️⃣2️⃣ Item size relative to residual
    let item_res_penalty = if item_size > 0 && res_f > 0.0 {
        let r = item_size as f64 / res_f;
        if r > 2.0 {
            (r - 2.0).powi(2) * 0.2
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 1️⃣3️⃣ Open‑bin count linear factor
    let open_factor = if open_bins_count > 20 {
        0.1 * (open_bins_count as f64)
    } else {
        0.0
    };

    base
        + fullness
        + dev
        + res_item
        + lookahead
        + new_bin
        + fitting_bias
        + perfect
        + dead
        + small
        + ratio_penalty
        + item_res_penalty
        + open_factor
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let res_f = bin_residual as f64;
    let res_frac = post_f / cap_f;

    // 1️⃣ Base cost – logarithmic residual
    let base = (post_f + 1.0).ln();

    // 2️⃣ Fullness pressure – favor highly utilised bins
    let fullness = (1.0 - res_frac).powi(2) * 5.0;

    // 3️⃣ Variance pressure – keep bins close to mean residual
    let dev = ((post_f - mean_residual).abs() / cap_f).powi(2) * 0.35;

    // 4️⃣ Small‑residual reuse bonus
    let small_res_bonus = if post_f > 0.0 && post_f < cap_f * 0.025 {
        -1.0
    } else {
        0.0
    };

    // 5️⃣ New‑bin penalty – reduced early in stream, scaled by open bins
    let new_bin_penalty = if bin_residual == bin_capacity {
        let early_factor = if step_index < total_items / 2 { 0.4 } else { 1.0 };
        let remaining_ratio = (total_items - step_index) as f64 / total_items as f64;
        let open_factor =
            ((open_bins_count as f64 + 1.0).ln() / (open_bins_count as f64 + 3.0).ln());
        let open_penalty = if open_bins_count > 25 {
            0.02 * open_bins_count as f64
        } else {
            0.0
        };
        3.0 * open_factor * remaining_ratio.powi(2) * early_factor + open_penalty
    } else {
        0.0
    };

    // 6️⃣ Open‑bin linear penalty – discourage too many bins
    let open_factor = if open_bins_count > 30 {
        0.05 * open_bins_count as f64
    } else {
        0.0
    };

    // 7️⃣ Fitting bias – encourage bins with many alternatives, penalise extremes
    let fitting_bias = if fitting_bins_count > 15 {
        -0.6
    } else if fitting_bins_count > 8 {
        -0.3
    } else {
        0.2
    };

    // 8️⃣ Perfect‑fit bonus
    let perfect = if post_f == 0.0 { -5.0 } else { 0.0 };

    // 9️⃣ Residual‑to‑next‑item ratio penalty for large waste
    let ratio_penalty = if next_item_size > 0 {
        let r = post_f / next_item_size as f64;
        if r > 1.2 {
            (r - 1.2).powi(2) * 0.3
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 🔟 Tight‑fit bonus – residual close to next item
    let tight_fit_bonus = if next_item_size > 0
        && post_f < next_item_size as f64
        && post_f > next_item_size as f64 * 0.95
    {
        -0.25
    } else {
        0.0
    };

    // 1️⃣1️⃣ Small residual reuse bonus (secondary)
    let small_residual_bonus = if post_f > 0.0 && post_f < cap_f * 0.05 {
        -0.5
    } else {
        0.0
    };

    // 1️⃣2️⃣ Lookahead dead‑space penalty
    let lookahead = if next_item_size > 0 && post_f >= next_item_size as f64 {
        let new_res = post_f - next_item_size as f64;
        if new_res > cap_f * 0.05 {
            ((new_res - cap_f * 0.05) / cap_f).powi(2) * 0.2
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 1️⃣3️⃣ Item‑size relative residual penalty
    let item_res_penalty = if item_size > 0 && post_f > 0.0 {
        let r = item_size as f64 / post_f;
        if r > 1.4 {
            (r - 1.4).powi(2) * 0.18
        } else {
            0.0
        }
    } else {
        0.0
    };

    // 1️⃣4️⃣ Mean residual deviation penalty
    let mean_dev_penalty = if (post_f - mean_residual).abs() > cap_f * 0.1 {
        ((post_f - mean_residual).abs() - cap_f * 0.1) / cap_f * 0.2
    } else {
        0.0
    };

    // 1️⃣5️⃣ Residual vs item size penalty
    let residual_vs_item = if post_f < item_size as f64 {
        ((item_size as f64 - post_f) / cap_f).powi(2) * 0.1
    } else {
        0.0
    };

    // Sum all components
    base
        + fullness
        + dev
        + small_res_bonus
        + new_bin_penalty
        + open_factor
        + fitting_bias
        + perfect
        + ratio_penalty
        + tight_fit_bonus
        + small_residual_bonus
        + lookahead
        + item_res_penalty
        + mean_dev_penalty
        + residual_vs_item
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let residual = post_residual as f64;
    let capacity = bin_capacity as f64;
    let residual_frac = residual / capacity;

    // 1️⃣ Log‑scaled base: higher residual → higher cost
    let base = (residual + 1.0).ln() * 1.15;

    // 2️⃣ Fullness penalty: favour bins that are closer to full
    let fullness = (1.0 - residual_frac).powi(2) * 9.5;

    // 3️⃣ Variance penalty: keep residuals balanced around the mean
    let dev = ((residual - mean_residual).powi(2)) * 0.28;

    // 4️⃣ Residual‑item coupling: penalise large leftover relative to item size
    let residual_item_ratio = if item_size > 0 {
        residual / item_size as f64
    } else {
        0.0
    };
    let residual_item_pen = residual_item_ratio.powi(2) * 0.5;

    // 5️⃣ Next‑item lookahead: if the next item will not fit after this placement
    let next_gap = if next_item_size > post_residual {
        ((next_item_size - post_residual) as f64).powi(2) * 0.75
    } else {
        0.0
    };

    // 6️⃣ New‑bin penalty: use logistic on open bin count and mean residual
    let mut new_bin_penalty = 0.0;
    if bin_residual == bin_capacity {
        let open_factor = open_bins_count as f64 / (open_bins_count as f64 + 12.0);
        let mean_factor = (mean_residual / capacity).ln().abs() + 1.0;
        let time_factor = if step_index > total_items / 2 { 0.6 } else { 1.0 };
        let base_pen = if open_bins_count > 10 { 8.0 } else if open_bins_count > 5 { 5.0 } else { 2.5 };
        new_bin_penalty = base_pen * open_factor * mean_factor * time_factor;
    }

    // 7️⃣ Fitting bias: prefer reusing a bin when many fit
    let fitting_bias = if fitting_bins_count > 3 { -0.8 } else { 1.2 };

    // 8️⃣ Perfect‑fit bonus
    let perfect_bonus = if residual == 0.0 { -3.0 } else { 0.0 };

    // 9️⃣ Large dead‑space penalty if residual exceeds next item by >1.5×
    let dead_space_pen = if residual > next_item_size as f64 * 1.5 {
        ((residual - next_item_size as f64 * 1.5).powi(2)) * 0.3
    } else {
        0.0
    };

    //  🔟 Combine all components
    base
        + fullness
        + dev
        + residual_item_pen
        + next_gap
        + new_bin_penalty
        + fitting_bias
        + perfect_bonus
        + dead_space_pen
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base penalty: logarithmic of the residual after placement.
    let base = (post_residual as f64 + 1.0).ln();

    // How tightly the item fills the bin before placement.
    let ratio = item_size as f64 / (bin_residual as f64 + 1.0);
    let ratio_penalty = (1.0 - ratio).powi(2) * 12.0;

    // Deviation from average residual across all bins.
    let residual_dev = (post_residual as f64 - mean_residual).abs() * 0.5;

    // Penalty if the next item will not fit.
    let next_fit_penalty = if next_item_size > post_residual { 20.0 } else { 0.0 };

    // New‑bin bias: discourage opening a new bin when many are already open.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if open_bins_count > 5 { 6.0 } else { 0.0 }
    } else { 0.0 };

    // Incentive to open a new bin when only one fitting bin exists.
    let fitting_bias = if fitting_bins_count == 1 { 3.0 } else { 0.0 };

    // Reward for a perfect fit.
    let perfect_fit_bonus = if post_residual == 0 { -1.0 } else { 0.0 };

    // Penalize high residual after placement (dead space).
    let dead_space_penalty = (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Bonus for placing items that almost fill the bin.
    let fit_density_bonus = if ratio > 0.95 {
        -2.5
    } else if ratio > 0.9 {
        -1.5
    } else {
        0.0
    };

    // Bonus if the next item fits in the same bin.
    let lookahead_bonus = if next_item_size <= post_residual { -3.0 } else { 0.0 };

    // Extra penalty for using many open bins.
    let open_bins_penalty = if open_bins_count > 8 { 4.0 } else { 0.0 };

    let mut score = base
        + ratio_penalty
        + residual_dev
        + next_fit_penalty
        + new_bin_penalty
        + fitting_bias
        + perfect_fit_bonus
        + dead_space_penalty
        + fit_density_bonus
        + lookahead_bonus
        + open_bins_penalty;

    // Slightly amplify penalties for later steps to encourage earlier packing.
    if step_index > total_items / 2 {
        score *= 1.05;
    }

    score
}
